using RvtIO.Internal;
using RvtIO.Model;
using RvtIO.Parsing;
using Xunit;

namespace RvtIO.Tests;

/// <summary>Pset_WallCommon.ExtendToStructure source: a wall's own JoinToRoofGStep
/// (class 2262) with m_baseOrTop = 1, read from its exact SWall root.</summary>
public class WallTopAttachmentTests
{
    // Exact SWall blocks (header + payload) of Test_2022.rvt. Wall 506386 is attached to
    // roof 243274 at its top (ExtendToStructure .T.); wall 745997 has no
    // JoinToRoofGStep (.F.).
    private const string TopAttachedWall =
        "";

    private const string UnattachedWall =
        "";

    // Block offsets inside JoinToRoofGStep of wall 506386.
    private const int JoinToRoofVersionOffset = 1521;
    private const int JoinToRoofBaseOrTopOffset = 1541;

    private static bool? Extract(byte[] block, ushort? classId = null) =>
        TfBlockDeserializer.ExtractWallJoinedToTop(
            block, 0, BitConverter.ToUInt32(block, 8),
            classId ?? BitConverter.ToUInt16(block, 12));

    [Fact]
    public void TopAttachedWall_IsJoinedToTop()
    {
        byte[] block = Convert.FromBase64String(TopAttachedWall);
        Assert.Equal(506386u, BitConverter.ToUInt32(block, 0));
        Assert.Equal(16, BitConverter.ToInt32(block, JoinToRoofVersionOffset));
        Assert.Equal(1, BitConverter.ToInt32(block, JoinToRoofBaseOrTopOffset));
        Assert.True(Extract(block));
    }

    [Fact]
    public void WallWithoutJoinToRoofStep_IsNotJoinedToTop()
    {
        byte[] block = Convert.FromBase64String(UnattachedWall);
        Assert.Equal(745997u, BitConverter.ToUInt32(block, 0));
        Assert.False(Extract(block));
    }

    [Theory]
    [InlineData(TopAttachedWall)]
    [InlineData(UnattachedWall)]
    public void WallRootNamedFieldsSurviveTheDeferredObjectsOfTheTailWalk(string base64)
    {
        // GeomGenerator.m_id of every geometry step shares the name of Element.m_id; the SWall tail walk must not let
        // the steps replace the wall's own id.
        byte[] block = Convert.FromBase64String(base64);
        var parameters = TfBlockDeserializer.ExtractParams(block, 0, BitConverter.ToUInt32(block, 8), BitConverter.ToUInt16(block, 12));
        Assert.NotNull(parameters);
        Assert.Equal((int)BitConverter.ToUInt32(block, 0), parameters.Fields["m_id"]);
    }

    [Fact]
    public void BaseAttachment_IsNotJoinedToTop()
    {
        byte[] block = Convert.FromBase64String(TopAttachedWall);
        BitConverter.GetBytes(0).CopyTo(block, JoinToRoofBaseOrTopOffset);
        Assert.False(Extract(block));
    }

    [Theory]
    [InlineData("base_or_top_range")]
    [InlineData("unknown_version")]
    [InlineData("footer")]
    [InlineData("data_size")]
    [InlineData("not_a_wall")]
    [InlineData("truncated")]
    public void UnreadableWallRoot_YieldsNoValue(string mutation)
    {
        byte[] block = Convert.FromBase64String(TopAttachedWall);
        ushort? classId = null;
        switch (mutation)
        {
            case "base_or_top_range":
                BitConverter.GetBytes(2).CopyTo(block, JoinToRoofBaseOrTopOffset);
                break;
            case "unknown_version":
                BitConverter.GetBytes(17).CopyTo(block, JoinToRoofVersionOffset);
                break;
            case "footer":
                block[^1] ^= 0xFF;
                break;
            case "data_size":
                BitConverter.GetBytes(BitConverter.ToUInt32(block, 8) + 1).CopyTo(block, 8);
                break;
            case "not_a_wall":
                classId = 3102;
                break;
            case "truncated":
                block = block[..(block.Length - 8)];
                break;
        }
        Assert.Null(mutation == "truncated"
            ? TfBlockDeserializer.ExtractWallJoinedToTop(
                block, 0, BitConverter.ToUInt32(block, 8), 3524)
            : Extract(block, classId));
    }

    // Exact SWall blocks of sample project A (ExtendToStructure .F.): 1984102 carries a
    // CutPairGStep v12 with a non-empty merged-face map; 581492 a WallShadowCutoutGStep v1.
    private const string SampleMergedFaceWall =
        "";

    private const string SampleShadowCutoutWall =
        "";

    [Theory]
    [InlineData(1984102u)]
    [InlineData(581492u)]
    public void SampleWallsWithLaterStepVersions_AreNotJoinedToTop(uint wallId)
    {
        byte[] block = Convert.FromBase64String(
            wallId == 1984102 ? SampleMergedFaceWall : SampleShadowCutoutWall);
        Assert.Equal(wallId, BitConverter.ToUInt32(block, 0));
        Assert.False(TfBlockDeserializer.ExtractWallJoinedToTop(
            block, 0, BitConverter.ToUInt32(block, 8), BitConverter.ToUInt16(block, 12),
            out string? failure));
        Assert.Null(failure);
    }

    [Fact]
    public void Apply_SetsOnlyUniqueWallsWithSingleReadableRoot()
    {
        var state = new ParsingState();
        state.WallJoinedToTop[1] = (1, true);
        state.WallJoinedToTop[2] = (1, false);
        state.WallJoinedToTop[3] = (2, null);
        state.WallJoinedToTop[4] = (1, null);
        state.WallJoinedToTop[5] = (1, true);
        state.WallJoinedToTop[6] = (1, true);
        var top = Wall(1);
        var unattached = Wall(2);
        var duplicateRoot = Wall(3);
        var unread = Wall(4);
        var notWall = Wall(5);
        notWall.CategoryId = -2000032;
        var duplicateElement = Wall(6);
        var elements = new List<Element>
            { top, unattached, duplicateRoot, unread, notWall, duplicateElement, Wall(6) };

        Assert.Equal(2, ElementBuilder.ApplyWallJoinedToTop(elements, state));
        Assert.True(top.SerializedWallJoinedToTop);
        Assert.False(unattached.SerializedWallJoinedToTop);
        Assert.Null(duplicateRoot.SerializedWallJoinedToTop);
        Assert.Null(unread.SerializedWallJoinedToTop);
        Assert.Null(notWall.SerializedWallJoinedToTop);
        Assert.Null(duplicateElement.SerializedWallJoinedToTop);
        Assert.Equal(1, top.Parameters.Single(p => p.Id == -1001117).Value);
        Assert.DoesNotContain(unattached.Parameters, p => p.Id == -1001117);
    }

    private static Element Wall(int id) => new() { Id = id, CategoryId = -2000011 };


    private static string Joins(byte[] block) => string.Join(";",
        TfBlockDeserializer.ExtractWallEndJoins(block, 0, BitConverter.ToUInt32(block, 8),
                BitConverter.ToUInt16(block, 12), out _)!
            .Select(join => $"{join.End}:{join.ElementId}:{join.JoinedEnd}"));

    [Theory]
    // Test_2022 745997: its start meets 599841's start, its end meets 765523's start; the
    // joins are (599841, 745997) ATSTART/ATSTART and (745997, 765523) ATEND/ATSTART.
    [InlineData(nameof(UnattachedWall), "0:599841:0;0:745997:0;1:745997:1;1:765523:0")]
    // Test_2022 506386: no control joins.
    [InlineData(nameof(TopAttachedWall), "")]
    // sample project A 1984102: its end meets 2375110's end (ATEND/ATEND).
    [InlineData(nameof(SampleMergedFaceWall), "1:1984102:1;1:2375110:1")]
    // sample project A 581492: both ends meet mid ends of 558818 and 581277 (ATPATH).
    [InlineData(nameof(SampleShadowCutoutWall), "0:558818:2;0:581492:0;1:581277:3;1:581492:1")]
    public void WallEndJoins_AreReadFromTheWallDriver(string fixture, string expected)
    {
        string base64 = fixture switch
        {
            nameof(UnattachedWall) => UnattachedWall,
            nameof(TopAttachedWall) => TopAttachedWall,
            nameof(SampleMergedFaceWall) => SampleMergedFaceWall,
            _ => SampleShadowCutoutWall,
        };
        Assert.Equal(expected, Joins(Convert.FromBase64String(base64)));
    }

    [Fact]
    public void WallEndJoins_NeedAnExactStepAfterTheDriver()
    {
        // One more EndInfo record than serialized shifts everything after the driver; the
        // first geometry step then no longer reads, so no joins are reported.
        byte[] block = Convert.FromBase64String(UnattachedWall);
        int neighbour = block.AsSpan().IndexOf(BitConverter.GetBytes(599841));
        Assert.True(neighbour > 4);
        uint count = BitConverter.ToUInt32(block, neighbour - 4);
        Assert.InRange(count, 1u, 8u);
        BitConverter.GetBytes(count + 1).CopyTo(block, neighbour - 4);
        Assert.Null(TfBlockDeserializer.ExtractWallEndJoins(block, 0, BitConverter.ToUInt32(block, 8),
            BitConverter.ToUInt16(block, 12), out _));

        byte[] wrongClass = Convert.FromBase64String(UnattachedWall);
        Assert.Null(TfBlockDeserializer.ExtractWallEndJoins(wrongClass, 0, BitConverter.ToUInt32(wrongClass, 8),
            2000, out _));
    }
}
